<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><base href="/SolarPower-Energy-Corporation/"><title>SOL-P tablet preview</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"><style>body{margin:0;background:#f2f7f4;font:16px Arial;color:#164d36}main{padding:24px;max-width:650px}main > button{padding:12px;margin:4px}.preview-note{line-height:1.6}</style></head><body><main><h1>SOL-P tablet animation</h1><p class="preview-note">Preview of the actual website mascot and CSS animation. Use Replay to watch the cover open, screen light up, and tablet close.</p><button id="replay">Replay tablet animation</button><button id="freeze">Show open tablet</button><button id="resume">Resume animation</button><p id="status" role="status">Ready</p></main><?php include __DIR__.'/../includes/faqChat.php';include __DIR__.'/../includes/floating_widgets.php';?><script>
const replay=document.querySelector('#replay'),freeze=document.querySelector('#freeze'),resume=document.querySelector('#resume');let cleanup;
function play(){clearTimeout(cleanup);const b=document.querySelector('.solp-button');b.classList.remove('is-assisting','is-hello','is-waving','is-excited');void b.offsetWidth;b.classList.add('is-assisting');document.querySelector('#status').textContent='Playing: opening, reading, closing';cleanup=setTimeout(()=>{b.classList.remove('is-assisting');document.querySelector('#status').textContent='Returned to idle';},6200);}
replay.onclick=play;freeze.onclick=()=>{play();clearTimeout(cleanup);document.querySelector('#solp-assistant').getAnimations({subtree:true}).forEach(a=>{a.pause();a.currentTime=3000});document.querySelector('#status').textContent='Paused at open tablet for inspection';};resume.onclick=()=>{document.querySelectorAll('#solp-assistant *').forEach(e=>e.getAnimations().forEach(a=>a.play()));play();};
</script></body></html>
